        /**
         * File failed to load.
         */
        var FILE_FAILED: number;

        /**
         * File is being processed (onProcess callback).
         */
        var FILE_PROCESSING: number;

        /**
         * The file encountered an error during processing.
         */
        var FILE_ERRORED: number;

        /**
         * File has finished processing.
         */
